//! Cargo-driven `normaliz.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", Some(0x6fd20000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", Some(0x7feb4000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", Some(0x7feb4000000u64)),
        o => panic!("normaliz-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("normaliz_shims", &["dll/nls/normaliz/IdnToAscii.c", "dll/nls/normaliz/IdnToUnicode.c", "dll/nls/normaliz/nameprep.c", "dll/nls/normaliz/normalize.c"])
        .spec2def("dll/nls/normaliz/normaliz.spec", "normaliz.dll")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
